import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor conv2d_bf16_forward(torch::Tensor x, torch::Tensor weight);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_bf16.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

#define TILE_H 16
#define TILE_W 16
#define REG_TILE 2
__global__ void conv2d_bf16_kernel(
    const __nv_bfloat16* __restrict__ X,
    const __nv_bfloat16* __restrict__ W,
    __nv_bfloat16* __restrict__ Y,
    int N, int Cin, int H, int Win,
    int Cout, int Kh, int Kw,
    int Hout, int Wout)
{
    extern __shared__ __nv_bfloat16 smem_raw[];
    const int n   = blockIdx.z;
    const int oh0 = blockIdx.y * TILE_H * REG_TILE;
    const int ow0 = blockIdx.x * TILE_W * REG_TILE;
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;
    const int tid = ty * TILE_W + tx;
    const int nthreads = TILE_H * TILE_W;
    const int tileH = TILE_H * REG_TILE + Kh - 1;
    const int tileW = TILE_W * REG_TILE + Kw - 1;
    // Shared memory layout: weights first, then the cooperatively-staged input tile
    __nv_bfloat16* sW_raw = smem_raw;
    const int wsize = Cout * Cin * Kh * Kw;
    __nv_bfloat16* sX_raw = smem_raw + wsize;
    const int xsize = Cin * tileH * tileW;
    // Cooperative load of the (small) full weight tensor into shared memory
    for (int i = tid; i < wsize; i += nthreads) {
        sW_raw[i] = W[i];
    }
    // Cooperative load of the input tile (with halo for the kernel window) into shared memory,
    // so that overlapping input elements are read from global memory only once per CTA instead
    // of once per output element. The tile now covers a larger REG_TILE x REG_TILE output block
    // per thread, amortizing weight/input reads via register blocking below.
    const int64_t sXn = (int64_t)Cin * H * Win;
    const __nv_bfloat16* Xn = X + (int64_t)n * sXn;
    for (int i = tid; i < xsize; i += nthreads) {
        int ci  = i / (tileH * tileW);
        int rem = i % (tileH * tileW);
        int r   = rem / tileW;
        int c   = rem % tileW;
        int gh  = oh0 + r;
        int gw  = ow0 + c;
        __nv_bfloat16 val = __float2bfloat16(0.0f);
        if (gh < H && gw < Win) {
            val = Xn[(int64_t)ci * H * Win + (int64_t)gh * Win + gw];
        }
        sX_raw[i] = val;
    }
    __syncthreads();
    // Build CUTE tensor views over global output and shared weights/input tile
    const int64_t sYn = (int64_t)Cout * Hout * Wout;
    auto mY = make_tensor(
        make_gmem_ptr(Y + (int64_t)n * sYn),
        make_shape(Cout, Hout, Wout),
        make_stride(Hout * Wout, Wout, Int<1>{})
    );
    auto mW = make_tensor(
        make_smem_ptr(sW_raw),
        make_shape(Cout, Cin, Kh, Kw),
        make_stride(Cin * Kh * Kw, Kh * Kw, Kw, Int<1>{})
    );
    auto mX = make_tensor(
        make_smem_ptr(sX_raw),
        make_shape(Cin, tileH, tileW),
        make_stride(tileH * tileW, tileW, Int<1>{})
    );
    // Register blocking: each thread computes a REG_TILE x REG_TILE block of outputs.
    // This reuses each weight value (loaded once from shared memory) across REG_TILE*REG_TILE
    // accumulators, and reuses each loaded input value only once but reduces the number of
    // shared-memory weight reads per output element and increases arithmetic intensity per thread.
    const int oh_base = oh0 + ty * REG_TILE;
    const int ow_base = ow0 + tx * REG_TILE;
    for (int co = 0; co < Cout; ++co) {
        float acc[REG_TILE][REG_TILE];
        #pragma unroll
        for (int dy = 0; dy < REG_TILE; ++dy) {
            #pragma unroll
            for (int dx = 0; dx < REG_TILE; ++dx) {
                acc[dy][dx] = 0.0f;
            }
        }
        #pragma unroll
        for (int ci = 0; ci < Cin; ++ci) {
            #pragma unroll
            for (int kh = 0; kh < Kh; ++kh) {
                #pragma unroll
                for (int kw = 0; kw < Kw; ++kw) {
                    float wv = __bfloat162float(mW(co, ci, kh, kw));
                    #pragma unroll
                    for (int dy = 0; dy < REG_TILE; ++dy) {
                        #pragma unroll
                        for (int dx = 0; dx < REG_TILE; ++dx) {
                            float xv = __bfloat162float(mX(ci, ty * REG_TILE + dy + kh, tx * REG_TILE + dx + kw));
                            acc[dy][dx] += xv * wv;
                        }
                    }
                }
            }
        }
        #pragma unroll
        for (int dy = 0; dy < REG_TILE; ++dy) {
            int oh = oh_base + dy;
            if (oh >= Hout) continue;
            #pragma unroll
            for (int dx = 0; dx < REG_TILE; ++dx) {
                int ow = ow_base + dx;
                if (ow >= Wout) continue;
                mY(co, oh, ow) = __float2bfloat16(acc[dy][dx]);
            }
        }
    }
}
torch::Tensor conv2d_bf16_forward(torch::Tensor x, torch::Tensor weight) {
    TORCH_CHECK(x.is_cuda(), "x must be CUDA");
    TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
    TORCH_CHECK(x.scalar_type() == at::kBFloat16, "x must be bfloat16");
    TORCH_CHECK(weight.scalar_type() == at::kBFloat16, "weight must be bfloat16");
    TORCH_CHECK(x.dim() == 4, "x must be [N, Cin, H, W]");
    TORCH_CHECK(weight.dim() == 4, "weight must be [Cout, Cin, Kh, Kw]");
    auto x_c = x.contiguous();
    auto w_c = weight.contiguous();
    int N    = (int)x_c.size(0);
    int Cin  = (int)x_c.size(1);
    int H    = (int)x_c.size(2);
    int Win  = (int)x_c.size(3);
    int Cout = (int)w_c.size(0);
    TORCH_CHECK((int)w_c.size(1) == Cin, "weight Cin mismatch");
    int Kh   = (int)w_c.size(2);
    int Kw   = (int)w_c.size(3);
    int Hout = H - Kh + 1;
    int Wout = Win - Kw + 1;
    TORCH_CHECK(Hout > 0 && Wout > 0, "Invalid output size (stride=1, padding=0 assumed)");
    auto y = torch::empty({N, Cout, Hout, Wout}, x.options());
    dim3 block(TILE_W, TILE_H);
    dim3 grid((Wout + TILE_W * REG_TILE - 1) / (TILE_W * REG_TILE),
               (Hout + TILE_H * REG_TILE - 1) / (TILE_H * REG_TILE),
               N);
    size_t smem_bytes = (size_t)(Cout * Cin * Kh * Kw + Cin * (TILE_H * REG_TILE + Kh - 1) * (TILE_W * REG_TILE + Kw - 1)) * sizeof(__nv_bfloat16);
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    conv2d_bf16_kernel<<<grid, block, smem_bytes, stream>>>(
        reinterpret_cast<const __nv_bfloat16*>(x_c.data_ptr<at::BFloat16>()),
        reinterpret_cast<const __nv_bfloat16*>(w_c.data_ptr<at::BFloat16>()),
        reinterpret_cast<__nv_bfloat16*>(y.data_ptr<at::BFloat16>()),
        N, Cin, H, Win, Cout, Kh, Kw, Hout, Wout
    );
    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "conv2d_bf16_kernel launch failed: ", cudaGetErrorString(err));
    return y;
}
